program.source:
Subroutine Swap(a As Integer, b As Integer)
  Define saved As Integer <- a;
  a <- b;
  b <- saved;
EndSubroutine

Algorithm Main
  Define primero, segundo As Integer;
  Read primero;
  Read segundo;
  Swap(primero, segundo);
  Write primero, " ", segundo;
EndAlgorithm

